WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT session_id, CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS new_group_flag_tier, CASE WHEN amount >= 4500 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN merchant = '7-Eleven' THEN 1 END), 0), 2) AS amount_per_7_eleven, COUNT(*) FILTER (WHERE merchant = 'Lazada') AS lazada_rows, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, COUNT(*) FILTER (WHERE merchant = 'Starbucks') AS starbucks_rows FROM sessions_transactions GROUP BY GROUPING SETS ((session_id, CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN amount >= 4500 THEN 'HIGH' ELSE 'LOW' END), (session_id, CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END), (session_id), ()) ORDER BY amount_tier DESC NULLS LAST;
